

`timescale 1ns/1ps

module axis_data_fifo_axis_dmadat_fifo #
(

  parameter integer AL_AXIS_TDATA_WIDTH = 16,
  parameter integer AL_AXIS_TID_WIDTH   = 1,
  parameter integer AL_AXIS_TDEST_WIDTH = 1,
  parameter integer AL_AXIS_TUSER_WIDTH = 1,
  parameter [31:0]  AL_AXIS_SIGNAL_SET  = 32'hFF,
  // AL_AXIS_SIGNAL_SET: each bit if enabled specifies which axis optional signals are present
  //   [0] => TREADY present
  //   [1] => TDATA present
  //   [2] => TSTRB present, TDATA must be present
  //   [3] => TKEEP present, TDATA must be present
  //   [4] => TLAST present
  //   [5] => TID present
  //   [6] => TDEST present
  //   [7] => TUSER present
  parameter integer AL_FIFO_DEPTH       = 512,
  //  Valid values 16,32,64,128,256,512,1024,2048,4096,...
  parameter integer AL_FIFO_MODE  = 1,
  // Values:
  //   0 == N0 FIFO
  //   1 == Regular FIFO
  //   2 == Store and Forward FIFO (Packet Mode). Requires TLAST.
  parameter integer AL_IS_ACLK_ASYNC    = 0,
  //  Enables async clock cross when 1.

  parameter integer AL_ACLKEN_CONV_MODE  = 1
  // AL_ACLKEN_CONV_MODE: Determines how to handle the clock enable pins during
  // clock conversion
  // 0 -- Clock enables not converted
  // 1 -- S_AXIS_ACLKEN can toggle,  M_AXIS_ACLKEN always high.
  // 2 -- S_AXIS_ACLKEN always high, M_AXIS_ACLKEN can toggle.
  // 3 -- S_AXIS_ACLKEN can toggle,  M_AXIS_ACLKEN can toggle.

  )
  (
  input  wire                            us_aclk,
  input wire                             us_aresetn,
  input  wire                            us_aclken,
  input  wire                            us_tvalid,
  output wire                            us_tready,
  input  wire [AL_AXIS_TDATA_WIDTH-1:0]   us_tdata,
  input  wire [AL_AXIS_TDATA_WIDTH/8-1:0] us_tstrb,
  input  wire [AL_AXIS_TDATA_WIDTH/8-1:0] us_tkeep,
  input  wire                            us_tlast,
  input  wire [AL_AXIS_TID_WIDTH-1:0]     us_tid,
  input  wire [AL_AXIS_TDEST_WIDTH-1:0]   us_tdest,
  input  wire [AL_AXIS_TUSER_WIDTH-1:0]   us_tuser,
  output wire                            almost_full,
  output wire [31:0]                     axis_wr_data_count,


  input  wire                            ds_aclk,
  input  wire                            ds_aclken,
  output wire                            ds_tvalid,
  input  wire                            ds_tready,
  output wire [AL_AXIS_TDATA_WIDTH-1:0]   ds_tdata,
  output wire [AL_AXIS_TDATA_WIDTH/8-1:0] ds_tstrb,
  output wire [AL_AXIS_TDATA_WIDTH/8-1:0] ds_tkeep,
  output wire                            ds_tlast,
  output wire [AL_AXIS_TID_WIDTH-1:0]     ds_tid,
  output wire [AL_AXIS_TDEST_WIDTH-1:0]   ds_tdest,
  output wire [AL_AXIS_TUSER_WIDTH-1:0]   ds_tuser,
  output wire                            almost_empty,
  output wire [31:0]                     axis_rd_data_count


  );


